SELECT channel, CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END AS order_cohort, SORT_ARRAY(COLLECT_SET(status)) AS status_list, MIN(shipping_fee) AS min_shipping_fee, MAX(shipping_fee) - MIN(shipping_fee) AS shipping_fee_range FROM orders GROUP BY ROLLUP(channel, CASE WHEN YEAR(order_date) < 2024 THEN 'before_2024' WHEN YEAR(order_date) = 2024 THEN '2024' ELSE 'after_2024' END);
